inline Selection select(Operation operation, rpu_pl_tiling::WeightType weight,
                        bool acc32, int rows, int n, int k) {
  if ((operation == Operation::A8Online || operation == Operation::A8External) &&
      weight == rpu_pl_tiling::WeightType::Int8 && acc32 && rows > 0 &&
      rows <= 65535 && n > 0 && n % 16 == 0 && k > 0 && k <= 65535 && k % 32 == 0) {
    const Profile* best = nullptr;
    std::array<uint64_t,5> best_score{};
    uint64_t best_x=0,best_y=0;
    for (const auto& p : profiles) {
      if (p.operation != operation) continue;
      const uint64_t mt=p.tile.m_tile,nt=p.tile.n_tile,kt=p.tile.k_tile;
      const uint64_t mb=(rows+mt-1)/mt,nb=(n+nt-1)/nt,kb=(k+kt-1)/kt;
      if (mb>65535 || nb>65535) continue;
      const uint64_t scan=operation==Operation::A8External ? 0 : 2ULL*rows*k;
      const std::array<uint64_t,5> score{{mb*nb*(nt*k+scan),mb*nb*kb,mb*nb*mt*nt,kt,nt}};
      if (!best || score<best_score) { best=&p;best_score=score;best_x=nb;best_y=mb; }
    }
    if (best) return {best->ordinal,best->tile,static_cast<uint16_t>(best_x),static_cast<uint16_t>(best_y)};
  }
  for (const auto& p : profiles)
    if (p.operation == operation && p.weight == weight && p.acc32 == acc32 &&
        p.rows == rows && p.n == n && p.k == k)
      return {p.ordinal, p.tile, p.grid_x, p.grid_y};
  throw std::invalid_argument("Unsupported current Pi/Wall projection profile");
}
